		&\approx_{\delta_Q} (\hat{S}_g)_{\alice \alice'} \otimes \Big ( \sum_{b,b'} 1_{\alpha b + \beta b' = g(x,z,\alpha,\beta)} \, \hat{M}^{(\Point,Z),z}_{b'} \hat{M}^{(\Point,X),x}_{b} \Big)_{\bob \alice''} \;.\label{eq:qld-g-43} 		
